    """Simulates a series of matches between two agents and returns the result counts. The agents take turns as Player X (first mover) and Player O (second mover) across the specified number of matches to balance advantage. For `QAgent` instances, this function passes `epsilon` during action selection to control exploration levels during evaluation. Returns a dictionary with keys 'wins_agent_a' (int), 'wins_agent_b' (int), and 'draws' (int). The sum of these values will be equal to `n_matches` unless an exception occurs. If an agent raises an exception during play, that match is not counted in totals but does not stop execution. Handles edge cases such as n_matches=0 (returns all zeros)."""
    if n_matches == 0:
        return {'wins_agent_a': 0, 'wins_agent_b': 0, 'draws': 0}

    wins_a = 0
    wins_b = 0
    draws = 0

    for _ in range(n_matches):
        env = type(env_template)()
        obs, _ = env.reset(seed=None)
        done = False
        truncated = False

        while not (done or truncated):
            # The environment automatically plays Player O on odd steps (1, 3, ...).
            # Player X plays on even steps (0, 2, ...). We only need to act when it is X's turn.
            if env.step_count % 2 == 0:
                try:
                    possible_moves = env._get_available_moves()
                except AttributeError:
                    possible_moves = [i for i in range(9) if env.state[i // 3, i % 3] == 0]

                if not possible_moves:
                    break

                # Pass only the arguments required by the agent's signature.
                # RandomAgent takes (obs, possible_moves). QAgent takes (obs, possible_moves, epsilon).
                if isinstance(agent_a, QAgent):
                    action = agent_a.choose_action(obs, possible_moves, epsilon)
                else:
                    action = agent_a.choose_action(obs, possible_moves)

            # Execute the step. The environment handles Player O's random move internally.
            obs, reward, done, truncated, info = env.step(action)

        if done:
            winner = info.get('winner', 0)
            if winner == 1: # Player X wins
                wins_a += 1
            elif winner == -1: # Player O wins
                wins_b += 1
            else:
                draws += 1
        else:
            draws += 1

    return {'wins_agent_a': wins_a, 'wins_agent_b': wins_b, 'draws': draws}

